motion:
/* hook: the swell slides under you, the aircraft rides it, the disc flickers; the question lands on the word */
tl.fromTo("#swell1", { x: 0 }, { x: -520, duration: 10.2, ease: "none" }, 2.7);
tl.fromTo("#h1", { y: 0 }, { y: -12, duration: 1.6, yoyo: true, repeat: 6, ease: "sine.inOut" }, 2.7);
tl.fromTo("#h1_disc", { opacity: 0.22 }, { opacity: 0.42, duration: 0.07, yoyo: true, repeat: 140, ease: "none" }, 2.7);
tl.fromTo("#qmark", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 10.0);
/* the plant: four bearings draw in to you on "tracking"; the tell on "That" */
["#b1", "#b2", "#b3", "#b4"].forEach((id, i) => tl.fromTo(id, { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.7, ease: "power1.inOut" }, 18.6 + i * 0.18));
tl.fromTo("#worry", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 20.6);
/* rule 1 obeyed: the tank fills to the brim, the percentage climbing with it */
tl.fromTo("#fuel", { height: 0 }, { height: 764, duration: 3.2, ease: "power1.inOut" }, 29.8);
for (let p = 0; p <= 100; p += 10) tl.set("#fpct", { textContent: String(p) }, 29.8 + (p / 100) * 3.2);
tl.fromTo("#brim", { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.3, ease: "power2.out" }, 33.0);
/* rule 2 obeyed: each item loads on its word, and the range pays for it */
[["w", 39.75, 170, "407"], ["m", 41.35, 6, "407"], ["r", 42.35, 26, "406"], ["f", 43.35, 520, "397"]].forEach(([k, t, w, r]) => {
  tl.to(`#bar_${k}`, { width: w, duration: 0.45, ease: "power2.out" }, t);
  tl.to(`#kg_${k}`, { opacity: 1, duration: 0.2 }, t);
  tl.set("#rng", { textContent: r }, t + 0.3);
});
/* you leave the food: the row is struck through, the bar empties, the range comes back */
tl.set("#bar_w2", { width: 170 }, 45.2); tl.set("#bar_m2", { width: 6 }, 45.2); tl.set("#bar_r2", { width: 26 }, 45.2); tl.set("#bar_f2", { width: 520 }, 45.2);
tl.set("#kg_w2,#kg_m2,#kg_r2,#kg_f2", { opacity: 1 }, 45.2); tl.set("#rng2", { textContent: "397" }, 45.2);
tl.to("#strike", { scaleX: 1, duration: 0.35, ease: "power2.out" }, 45.7);
tl.to("#bar_f2", { width: 0, duration: 0.5, ease: "power2.inOut" }, 46.5);
tl.fromTo("#ground", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.3, ease: "power3.out" }, 46.5);
tl.set("#rng2", { textContent: "406" }, 48.4);
/* rule 3 obeyed: four hundred miles of nothing, crossed */
tl.to("#helidot", { attr: { cy: 920 }, duration: 4.6, ease: "none" }, 55.4);
/* 11:40: the gauge, and what she says */
tl.fromTo("#fuelbar", { width: "49%" }, { width: "45%", duration: 8.0, ease: "none" }, 60.1);
tl.set("#oneway", { textContent: "" }, 60.1);
tl.to("#oneway", { duration: 1.0, scrambleText: { text: "ONE WAY", chars: "upperCase", speed: 0.7 } }, 66.35);
/* the other thing */
tl.set("#askq", { textContent: "" }, 68.3);
tl.to("#askq", { duration: 1.6, scrambleText: { text: "WHO HAVE YOU BEEN TALKING TO?", chars: "upperCase", speed: 0.6 } }, 70.65);
/* the recall: three nights, three listens, and a key never pressed */
[[75.35, "#d1"], [75.95, "#d3"], [76.7, "#d5"]].forEach(([t, id]) => tl.fromTo(id, { opacity: 0, y: 10 }, { opacity: 1, y: 0, duration: 0.25, ease: "power2.out" }, t));
tl.to("#txnever", { opacity: 1, duration: 0.3 }, 78.25);
/* the twist: never spoken; then the bearings draw in, in red, on "tracking" */
tl.fromTo("#neverstamp", { scale: 1.8, opacity: 0 }, { scale: 1, opacity: 1, duration: 0.32, ease: "power3.out" }, 80.6);
["#t1", "#t2", "#t3", "#t4"].forEach((id, i) => tl.fromTo(id, { drawSVG: "0% 0%" }, { drawSVG: "0% 100%", duration: 0.5, ease: "power2.in" }, 84.3 + i * 0.12));
tl.fromTo("#tracked", { opacity: 0, scale: 1.4 }, { opacity: 1, scale: 1, duration: 0.3, ease: "power3.out" }, 84.95);
